local QuillMenderMaker = {}
local PRODUCTS = {
    iron_quillmender = { name = "Železni popravljalec peres", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni popravljalec peres za pisarje." },
    bronze_quillmender = { name = "Bronast popravljalec peres", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast popravljalec peres za pisarje." },
    silver_quillmender = { name = "Srebrn popravljalec peres", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn popravljalec peres za pisarje." },
    gilded_quillmender = { name = "Pozlačen popravljalec peres", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen popravljalec peres za pisarje." },
    jewel_set_quillmender = { name = "Draguljast popravljalec peres", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast popravljalec peres za pisarje." },
    royal_sovereign_quillmender = { name = "Kraljevski suveren popravljalec peres", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren popravljalec peres z biseri za krono." },
}
local BUILDINGS = {
    quillmender_workshop = { name = "Quillmender delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    quillmender_house = { name = "Quillmender hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_quillmender_atelier = { name = "Mojstrski quillmender atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_quillmender_palace = { name = "Suverena quillmender palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
QuillMenderMaker.ironStock=14; QuillMenderMaker.bronzeStock=12; QuillMenderMaker.woodStock=12; QuillMenderMaker.leatherStock=10; QuillMenderMaker.silverStock=8; QuillMenderMaker.goldStock=6; QuillMenderMaker.jewelStock=4; QuillMenderMaker.pearlStock=4
QuillMenderMaker.productStock = {}; QuillMenderMaker.buildings = {}; QuillMenderMaker.maker = nil; QuillMenderMaker.activeMaking = {}; QuillMenderMaker.totalProducts = 0; QuillMenderMaker.dayTimer = 0
function QuillMenderMaker.init() QuillMenderMaker.ironStock=14; QuillMenderMaker.bronzeStock=12; QuillMenderMaker.woodStock=12; QuillMenderMaker.leatherStock=10; QuillMenderMaker.silverStock=8; QuillMenderMaker.goldStock=6; QuillMenderMaker.jewelStock=4; QuillMenderMaker.pearlStock=4; QuillMenderMaker.productStock={}; QuillMenderMaker.buildings={}; QuillMenderMaker.maker=nil; QuillMenderMaker.activeMaking={}; QuillMenderMaker.totalProducts=0; QuillMenderMaker.dayTimer=0; print("[QuillMenderMaker] Royal Quill Mender Maker System initialized (6 products, 4 buildings)") end
function QuillMenderMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; QuillMenderMaker.maker={name=n or ("Popravljalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Popravljalec najet: %s (spretnost: %d)",QuillMenderMaker.maker.name,s),"success") end; return true end
function QuillMenderMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function QuillMenderMaker.build(id) local ok,e=QuillMenderMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(QuillMenderMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function QuillMenderMaker.getQualityBonus() local b=0; for _,bd in ipairs(QuillMenderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function QuillMenderMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and QuillMenderMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and QuillMenderMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and QuillMenderMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and QuillMenderMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and QuillMenderMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and QuillMenderMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and QuillMenderMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and QuillMenderMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #QuillMenderMaker.buildings==0 then return false,"Potrebna popravljena delavnica" end; if not QuillMenderMaker.maker then return false,"Potreben popravljalec" end; return true end
function QuillMenderMaker.make(pt,qty) qty=qty or 1; local ok,e=QuillMenderMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then QuillMenderMaker.ironStock=QuillMenderMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then QuillMenderMaker.bronzeStock=QuillMenderMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then QuillMenderMaker.woodStock=QuillMenderMaker.woodStock-d.woodCost*qty end; if d.leatherCost then QuillMenderMaker.leatherStock=QuillMenderMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then QuillMenderMaker.silverStock=QuillMenderMaker.silverStock-d.silverCost*qty end; if d.goldCost then QuillMenderMaker.goldStock=QuillMenderMaker.goldStock-d.goldCost*qty end; if d.jewelCost then QuillMenderMaker.jewelStock=QuillMenderMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then QuillMenderMaker.pearlStock=QuillMenderMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if QuillMenderMaker.maker then t=math.max(1,t-math.floor(QuillMenderMaker.maker.skill/13)) end; table.insert(QuillMenderMaker.activeMaking,{id="quillmender_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function QuillMenderMaker.completeMaking(m) local q=1.0+(QuillMenderMaker.getQualityBonus()/100); if QuillMenderMaker.maker then q=q+(QuillMenderMaker.maker.skill/140) end; q=math.min(2.5,q); QuillMenderMaker.productStock[m.productType]=(QuillMenderMaker.productStock[m.productType] or 0)+m.quantity; QuillMenderMaker.totalProducts=QuillMenderMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if QuillMenderMaker.maker then QuillMenderMaker.maker.itemsMade=QuillMenderMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then QuillMenderMaker.maker.skill=math.min(100,QuillMenderMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Popravljalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"quillmender.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function QuillMenderMaker.update(dt) if not _G.state then return end; QuillMenderMaker.dayTimer=QuillMenderMaker.dayTimer+dt; if QuillMenderMaker.dayTimer>=30 then QuillMenderMaker.dayTimer=0; for i=#QuillMenderMaker.activeMaking,1,-1 do local m=QuillMenderMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then QuillMenderMaker.completeMaking(m); table.remove(QuillMenderMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(QuillMenderMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if QuillMenderMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function QuillMenderMaker.getStats() return {ironStock=QuillMenderMaker.ironStock,bronzeStock=QuillMenderMaker.bronzeStock,woodStock=QuillMenderMaker.woodStock,leatherStock=QuillMenderMaker.leatherStock,silverStock=QuillMenderMaker.silverStock,goldStock=QuillMenderMaker.goldStock,jewelStock=QuillMenderMaker.jewelStock,pearlStock=QuillMenderMaker.pearlStock,productStock=QuillMenderMaker.productStock,numBuildings=#QuillMenderMaker.buildings,hasMaker=QuillMenderMaker.maker~=nil,makerName=QuillMenderMaker.maker and QuillMenderMaker.maker.name or "—",makerSkill=QuillMenderMaker.maker and QuillMenderMaker.maker.skill or 0,activeMaking=#QuillMenderMaker.activeMaking,totalProducts=QuillMenderMaker.totalProducts} end
return QuillMenderMaker
